// ---------------------------------------------------------------------------
// CLI argument parsing (deliberately dependency-free)
// ---------------------------------------------------------------------------

interface CliArgs {
  thresholds: number[];
}

function printUsage(): void {
  process.stderr.write(
    [
      "Alchemyst AI Threshold Sensitivity CLI",
      "",
      "Usage:",
      "  node dist/main.js --thresholds <csv>",
      "",
      "Arguments:",
      "  --thresholds <csv>   Comma-separated similarity_threshold values",
      "                       in the range [0, 1] (e.g. 0.5,0.7,0.9).",
      "  -h, --help           Show this help message and exit.",
      "",
      "Environment variables:",
      "  ALCHEMYST_AI_API_KEY   Required. Alchemyst AI API key.",
      "",
    ].join("\n"),
  );
}

function parseCliArgs(argv: readonly string[]): CliArgs {
  const out: CliArgs = { thresholds: [] };
  for (let i = 2; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === "-h" || arg === "--help") {
      printUsage();
      process.exit(0);
    }

    if (arg === "--thresholds") {
      const next = argv[i + 1];
      if (next === undefined || next.startsWith("--")) {
        throw new Error("Missing value for --thresholds");
      }
      const parts = next.split(",").map((s) => s.trim()).filter((s) => s.length > 0);
      for (const p of parts) {
        const num = Number(p);
        if (!Number.isFinite(num)) {
          throw new Error(`Invalid threshold value: "${p}" (not a number)`);
        }
        if (num < 0 || num > 1) {
          throw new Error(`Invalid threshold value: "${p}" (must be in [0, 1])`);
        }
        out.thresholds.push(num);
      }
      i++; // consumed the value
      continue;
    }

    if (arg.startsWith("--")) {
      throw new Error(`Unknown option: ${arg}`);
    }
  }

  if (out.thresholds.length === 0) {
    throw new Error("At least one threshold value is required via --thresholds.");
  }

  return out;
}

