// Helpers
// ---------------------------------------------------------------------------

/**
 * Read the run-id file, trim it, and sanitise it so it is safe to embed in a
 * `fileName`. If the file is missing/empty we abort with a non-zero exit so
 * the test harness sees a clear failure rather than silent fallback.
 */
function readRunId(filePath: string): string {
  let raw: string;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    throw new Error(`Unable to read run-id from ${filePath}: ${reason}`);
  }
  const trimmed = raw.trim();
  if (!trimmed) {
    throw new Error(`Run-id file ${filePath} is empty`);
  }
  // Sanitise: keep only [A-Za-z0-9_-], replace everything else with '_'.
  return trimmed.replace(/[^A-Za-z0-9_-]/g, "_");
}

/** Tiny sleep used for retry/backoff between API calls. */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Run `client.v1.context.add` for a list of documents in one batch.
 * Documents get a unique `fileName` that includes the run-id so concurrent
 * runs do not collide, while re-runs within the same run-id share the same
 * file_name and produce a 409 (which we treat as success).
 */
async function ingestCorpus(
  client: AlchemystAI,
  runId: string,
): Promise<void> {
  const documents = CORPUS.map((item, idx) => ({
    content: item.content,
    fileName: `threshold_doc_${String(idx).padStart(2, "0")}_${runId}.md`,
  }));

  const payload = {
    documents,
    context_type: "resource" as const,
    source: SOURCE,
    scope: SCOPE,
    metadata: {
      fileType: "text/markdown",
      groupName: ["threshold-demo", `run-${runId}`],
    },
  };

  try {
    await client.v1.context.add(payload);
    process.stderr.write(
      `[ok] Ingested ${documents.length} corpus documents for run-id=${runId}.\n`,
    );
  } catch (err) {
    if (isConflictError(err)) {
      // 409 Conflict means the documents already exist from a previous run
      // — that is the idempotency contract we want.
      process.stderr.write(
        `[ok] Corpus for run-id=${runId} already exists (409), continuing.\n`,
      );
      return;
    }
    throw err;
  }
}

/** Type-narrowed 409 detection. */
function isConflictError(err: unknown): boolean {
  return err instanceof APIError && err.status === 409;
}

/** True for any 4xx/5xx the SDK exposes as an APIError. */
function isApiError(err: unknown): err is APIError {
  return err instanceof APIError;
}

/**
 * Search the corpus with the given `similarity_threshold` and return the
 * number of contexts returned. Includes a small exponential backoff retry
 * loop on rate limits (429) as recommended by the docs.
 */
async function searchCount(
  client: AlchemystAI,
  threshold: number,
): Promise<number> {
  const maxAttempts = 4;
  let attempt = 0;
  let lastError: unknown;

  while (attempt < maxAttempts) {
    attempt++;
    try {
      const resp = await client.v1.context.search({
        query: FIXED_QUERY,
        similarity_threshold: threshold,
        // minimum_similarity_threshold must be <= similarity_threshold.
        minimum_similarity_threshold: Math.max(0, threshold - 0.1),
        scope: SCOPE,
      });

      const ctxs = resp.contexts;
      return Array.isArray(ctxs) ? ctxs.length : 0;
    } catch (err) {
      lastError = err;
      if (isApiError(err) && err.status === 429 && attempt < maxAttempts) {
        const wait = 500 * Math.pow(2, attempt - 1);
        process.stderr.write(
          `[retry] rate-limited on threshold=${threshold}, attempt ${attempt}; sleeping ${wait}ms\n`,
        );
        await sleep(wait);
        continue;
      }
      throw err;
    }
  }

  // Exhausted retries.
  throw lastError instanceof Error
    ? lastError
    : new Error(`search failed for threshold=${threshold}`);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  // 1. Parse CLI args first so `--help` works even without an API key.
  const args = parseCliArgs(process.argv);

  // 2. Verify the API key is present (fail with non-zero exit if missing).
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey || apiKey.trim() === "") {
    process.stderr.write(
      "Error: ALCHEMYST_AI_API_KEY environment variable is not set.\n",
    );
    process.exit(2);
  }

  // 3. Read run-id (used to namespace `file_name` so concurrent runs do not collide).
  const runId = readRunId(RUN_ID_PATH);
  process.stderr.write(`[info] using run-id=${runId}\n`);

  // 4. Build client and ingest the corpus.
  const client = new AlchemystAI({ apiKey });

  await ingestCorpus(client, runId);

  // 5. For each threshold, search and capture the count. We run searches in
  //    parallel because they are independent reads against the same index;
  //    Promise.all preserves the order of the input array.
  const results = await Promise.all(
    args.thresholds.map(async (threshold) => {
      const count = await searchCount(client, threshold);
      process.stderr.write(
        `[ok] threshold=${threshold} returned count=${count}\n`,
      );
      return { threshold, count };
    }),
  );

  // 6. Emit exactly one JSON object on stdout. No other stdout writes.
  const out = { query: FIXED_QUERY, results };
  process.stdout.write(JSON.stringify(out) + "\n");
}

